import os
from openai import OpenAI

client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY", "mock-key"))

# Công cụ thực tế của Agent
def get_current_stock_price(symbol: str) -> str:
    # Giả lập gọi API sàn chứng khoán
    stocks = {"AAPL": "180.5 USD", "VNM": "68,000 VND"}
    return stocks.get(symbol.upper(), "Không tìm thấy mã")

# Khai báo schema công cụ chuẩn mực cho LLM Agent
tools_schema = [
    {
        "type": "function",
        "function": {
            "name": "get_current_stock_price",
            "description": "Lấy giá cổ phiếu hiện tại theo mã chứng khoán",
            "parameters": {
                "type": "object",
                "properties": {
                    "symbol": {"type": "string", "description": "Mã cổ phiếu ví dụ AAPL, VNM"}
                },
                "required": ["symbol"]
            }
        }
    }
]

def run_simple_agent(user_goal: str):
    """Mô phỏng 1 chu trình ReAct của AI Agent: Quyết định gọi tool và phản hồi."""
    messages = [{"role": "user", "content": user_goal}]

    # Bước 1: Agent suy luận và quyết định hành động (Tool Call)
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=messages,
        tools=tools_schema,
        tool_choice="auto"
    )

    msg = response.choices[0].message
    if msg.tool_calls:
        tool_call = msg.tool_calls[0]
        fn_name = tool_call.function.name
        # Giả lập thực thi tool
        tool_result = get_current_stock_price("VNM")
        print(f"[Agent Action] Gọi công cụ '{fn_name}' -> Kết quả: {tool_result}")

if __name__ == "__main__":
    run_simple_agent("Giá cổ phiếu VNM hôm nay thế nào?")

