# 1. Thư viện cứu hộ JSON hỏng: pip install json-repair
# import json_repair

def robust_json_parser(raw_llm_output: str, finish_reason: str = "stop") -> dict:
    """Hàm bọc xử lý JSON đa tầng chuẩn Enterprise chống crash ứng dụng."""
    # Kiểm tra nếu bị cắt cụt do hết token quota
    if finish_reason == "length":
        raise ValueError("Lỗi: JSON bị cắt cụt giữa chừng do vượt quá max_tokens!")

    # Bước 1: Thử parse trực tiếp
    try:
        return json.loads(raw_llm_output)
    except json.JSONDecodeError:
        pass

    # Bước 2: Dùng Regex bóc tách khối JSON nằm giữa chữ thừa hoặc markdown
    match = re.search(r"(\{.*\}|\[.*\])", raw_llm_output, re.DOTALL)
    if match:
        clean_text = match.group(0)
        try:
            return json.loads(clean_text)
        except json.JSONDecodeError:
            pass

    # Bước 3: Cứu hộ bằng thuật toán tự vá dấu ngoặc (Heuristic repair)
    # return json_repair.repair_json(raw_llm_output, return_objects=True)
    raise ValueError(f"Không thể parse JSON từ phản hồi: {raw_llm_output[:100]}...")

if __name__ == "__main__":
    messy_output = "Chào bạn! Đây là dữ liệu bạn cần:\n```json\n{\"status\": \"success\", \"code\": 200}\n```\nChúc bạn một ngày tốt lành!"
    parsed = robust_json_parser(messy_output)
    print("Parsed JSON an toàn:", parsed)

