# Minh họa thuật toán Reciprocal Rank Fusion (RRF) kết hợp Dense và Sparse Search
def reciprocal_rank_fusion(
    dense_results: list[str], 
    sparse_results: list[str], 
    k: int = 60
) -> list[tuple[str, float]]:
    """Gộp và xếp hạng kết quả từ Dense Vector Search và Sparse BM25 Search."""
    rrf_scores = {}

    # Chấm điểm kết quả Dense (Vector)
    for rank, doc_id in enumerate(dense_results):
        if doc_id not in rrf_scores:
            rrf_scores[doc_id] = 0.0
        rrf_scores[doc_id] += 1.0 / (k + rank + 1)

    # Chấm điểm kết quả Sparse (BM25)
    for rank, doc_id in enumerate(sparse_results):
        if doc_id not in rrf_scores:
            rrf_scores[doc_id] = 0.0
        rrf_scores[doc_id] += 1.0 / (k + rank + 1)

    # Sắp xếp các tài liệu theo điểm RRF giảm dần
    sorted_docs = sorted(rrf_scores.items(), key=lambda item: item[1], reverse=True)
    return sorted_docs

if __name__ == "__main__":
    dense_hits = ["doc_A", "doc_B", "doc_C"] # Vector search hiểu ngữ nghĩa
    sparse_hits = ["doc_B", "doc_D", "doc_A"] # BM25 search bắt trúng keyword

    ranked = reciprocal_rank_fusion(dense_hits, sparse_hits)
    print("Xếp hạng kết hợp Hybrid RRF:")
    for doc, score in ranked:
        print(f"- {doc}: RRF Score = {score:.4f}")
    # doc_B xuất hiện cao ở cả 2 bên -> Đạt điểm số RRF cao nhất!

