import json

class AgentMemoryStore:
    def __init__(self):
        # Bộ nhớ dài hạn lưu trữ sở thích của từng User vĩnh viễn trong Database
        self.user_long_term_profile = {}

    def extract_and_save_facts(self, user_id: str, conversation_text: str):
        """Hàm chạy ngầm (Background Task) trích xuất sự thật vào Long-term Memory."""
        # Giả lập LLM trích xuất các facts quan trọng từ cuộc trò chuyện
        # Trong thực tế: LLM gọi hàm với schema {"dietary": "vegetarian", "timezone": "UTC+7"}
        extracted_facts = {"dietary_preference": "Ăn chay", "favorite_city": "Đà Lạt"}

        if user_id not in self.user_long_term_profile:
            self.user_long_term_profile[user_id] = {}
        self.user_long_term_profile[user_id].update(extracted_facts)
        print(f"[Long-term Memory] Đã lưu thông tin bền vững cho {user_id}: {extracted_facts}")

    def build_system_prompt_with_memory(self, user_id: str) -> str:
        """Nạp bộ nhớ dài hạn vào System Prompt cho phiên chat tiếp theo."""
        profile = self.user_long_term_profile.get(user_id, {})
        memory_context = "\n".join(f"- {k}: {v}" for k, v in profile.items())

        return f"""Bạn là trợ lý cá nhân chu đáo.
Hồ sơ ghi nhớ về người dùng:
{memory_context}
Hãy cá nhân hóa câu trả lời dựa trên các thông tin trên."""

if __name__ == "__main__":
    store = AgentMemoryStore()
    store.extract_and_save_facts("user_101", "Tôi là người ăn chay, tuần sau tôi muốn đi Đà Lạt...")
    prompt = store.build_system_prompt_with_memory("user_101")
    print("\nPrompt được cá nhân hóa:\n", prompt)

# Mô phỏng kiến trúc Human-in-the-loop (HITL) cho hành động tài chính nhạy cảm
class FinancialAgentWithHITL:
    def __init__(self):
        self.pending_approvals = {}

    def propose_action(self, action_id: str, tool_name: str, params: dict) -> dict:
        """Bước 1: Agent chỉ đề xuất hành động và tạm dừng chờ phê duyệt."""
        if tool_name == "execute_bank_transfer" and params.get("amount", 0) > 1000:
            # Rủi ro cao: Lưu trạng thái và yêu cầu con người duyệt
            self.pending_approvals[action_id] = {"tool": tool_name, "params": params, "status": "PENDING"}
            return {
                "status": "SUSPENDED",
                "message": f"Hành động chuyển tiền {params['amount']}$ cần phê duyệt của Quản lý!",
                "action_id": action_id
            }
        else:
            return {"status": "EXECUTED", "result": "Thực hiện tự động thành công"}

    def human_review_decision(self, action_id: str, approved: bool) -> str:
        """Bước 2: Con người can thiệp phê duyệt hoặc từ chối hành động."""
        pending = self.pending_approvals.get(action_id)
        if not pending:
            return "Không tìm thấy hành động đang chờ."

        if approved:
            pending["status"] = "APPROVED"
            # Thực hiện hành động thật sự sau khi có chữ ký duyệt
            return f"ĐÃ THỰC THI: Chuyển thành công {pending['params']['amount']}$ cho {pending['params']['to_account']}."
        else:
            pending["status"] = "REJECTED"
            return "ĐÃ HỦY: Người quản trị từ chối giao dịch này."

if __name__ == "__main__":
    agent = FinancialAgentWithHITL()
    proposal = agent.propose_action("tx_9921", "execute_bank_transfer", {"amount": 5000, "to_account": "ACC_888"})
    print("Agent Response:", proposal)

    # Quản trị viên duyệt trên giao diện
    decision = agent.human_review_decision("tx_9921", approved=True)
    print("Human Decision Result:", decision)

# Bảng điều phối lựa chọn Framework chuẩn cho từng bài toán AI
def recommend_ai_framework(use_case_type: str) -> dict:
    """Tư vấn lựa chọn giữa LlamaIndex, LangGraph và LangChain."""
    if use_case_type == "advanced_rag":
        return {
            "framework": "LlamaIndex",
            "strengths": "Bộ parser tài liệu tốt nhất, hỗ trợ Parent-child, Auto-merging, Router query engines.",
            "avoid": "Đừng cố dùng LlamaIndex để dựng complex multi-agent state machines."
        }
    elif use_case_type == "multi_agent_workflow":
        return {
            "framework": "LangGraph",
            "strengths": "Mô hình hóa chu trình Agent bằng State Graph, hỗ trợ Cycles, Time-travel debugging, Human-in-the-loop.",
            "avoid": "Không dùng các legacy LCEL chains cũ của LangChain."
        }
    else:
        return {
            "framework": "Native OpenAI SDK + Pydantic (No Heavy Framework)",
            "strengths": "Đơn giản, tốc độ cao nhất, zero abstraction, dễ bảo trì và debug."
        }

if __name__ == "__main__":
    rec = recommend_ai_framework("multi_agent_workflow")
    print(f"Lựa chọn: {rec['framework']}\nƯu thế: {rec['strengths']}")

