from typing import List, Dict

def validate_finetuning_dataset(file_path: str) -> dict:
    """Kiểm tra cú pháp, cấu trúc vai trò và độ dài của file JSONL trước khi nạp vào fine-tune."""
    total_samples = 0
    errors = []

    with open(file_path, "r", encoding="utf-8") as f:
        for line_num, line in enumerate(f, start=1):
            total_samples += 1
            try:
                record = json.loads(line)
                messages: List[Dict] = record.get("messages", [])

                # Kiểm tra cấu trúc tối thiểu phải có system, user, assistant
                roles = [m.get("role") for m in messages]
                if "user" not in roles or "assistant" not in roles:
                    errors.append(f"Dòng {line_num}: Thiếu vai trò user hoặc assistant")

                # Kiểm tra nội dung rỗng
                for m in messages:
                    if not m.get("content", "").strip():
                        errors.append(f"Dòng {line_num}: Chứa nội dung tin nhắn rỗng!")

            except json.JSONDecodeError:
                errors.append(f"Dòng {line_num}: Cú pháp JSON không hợp lệ!")

    return {
        "total_samples": total_samples,
        "is_valid": len(errors) == 0,
        "errors": errors[:5] # Hiển thị 5 lỗi đầu tiên
    }

