def run_agent(user_query: str):
    messages = [{"role": "user", "content": user_query}]

    while True:
        response = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=messages,
            tools=tools,
            tool_choice="auto"
        )
        msg = response.choices[0].message
        messages.append(msg)

        # Nếu model không gọi thêm tool nào -> Đã có câu trả lời cuối cùng
        if not msg.tool_calls:
            return msg.content

        # Nếu model yêu cầu gọi tool -> Thực thi từng tool được yêu cầu
        for tool_call in msg.tool_calls:
            fn_name = tool_call.function.name
            args = json.loads(tool_call.function.arguments)
            print(f"[Agent Calling Tool] {fn_name}({args})")

            if fn_name == "calculate":
                result = calculate_expression(args.get("expression", ""))
            elif fn_name == "search_web":
                result = mock_search_web(args.get("query", ""))
            else:
                result = "Unknown tool"

            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": result
            })

