class PromptABRouter:
    def __init__(self, active_version: str = "v1.0.0", canary_version: str = "v1.1.0", traffic_split_canary: int = 20):
        self.active_version = active_version
        self.canary_version = canary_version
        self.traffic_split = traffic_split_canary  # 20% traffic sang phiên bản mới

    def get_prompt_config(self, user_id: str, query: str) -> dict:
        # Băm user_id để đảm bảo cùng 1 user luôn nhận cùng 1 version
        hash_val = int(hashlib.md5(user_id.encode()).hexdigest(), 16) % 100
        chosen_ver = self.canary_version if hash_val < self.traffic_split else self.active_version

        cfg = PROMPT_REGISTRY[chosen_ver]
        formatted_prompt = cfg["template"].format(query=query)
        return {
            "version": chosen_ver,
            "model": cfg["model"],
            "temperature": cfg["temperature"],
            "system_prompt": formatted_prompt
        }

