import uuid

class ParentDocumentStore:
    def __init__(self):
        self.parent_storage = {}  # Key-Value: parent_id -> Full text
        self.child_vectors = []   # Vector Index: (vector, parent_id)

    def ingest_document(self, long_text: str, parent_chunk_size: int = 1000, child_chunk_size: int = 200):
        # 1. Cắt thành các Parent chunks lớn
        for i in range(0, len(long_text), parent_chunk_size):
            parent_id = str(uuid.uuid4())
            parent_content = long_text[i:i + parent_chunk_size]
            self.parent_storage[parent_id] = parent_content

            # 2. Cắt Parent chunk thành các Child chunks nhỏ để nhúng vector
            for j in range(0, len(parent_content), child_chunk_size):
                child_content = parent_content[j:j + child_chunk_size]
                # Trong thực tế: embed child_content và lưu vào Vector DB
                self.child_vectors.append({
                    "child_text": child_content,
                    "parent_id": parent_id
                })

    def retrieve(self, query: str) -> list[str]:
        # Giả lập tìm kiếm: Tìm trúng 1 child chunk
        matched_child = self.child_vectors[0]
        parent_id = matched_child["parent_id"]

        # Thay vì trả về child_text cụt lủn, trả về Parent Chunk trọn vẹn ngữ cảnh!
        full_parent_context = self.parent_storage[parent_id]
        return [full_parent_context]

import time
from typing import Optional

class FallbackAIGateway:
    def __init__(self, primary_client, fallback_client):
        self.primary = primary_client
        self.fallback = fallback_client
        self.failure_count = 0
        self.circuit_open_until = 0.0

    def call_llm(self, prompt: str) -> str:
        current_time = time.time()

        # Nếu Circuit Breaker đang MỞ (đang trong thời gian cách ly nhà cung cấp chính)
        if current_time < self.circuit_open_until:
            print("[CIRCUIT OPEN] Đang định tuyến trực tiếp sang Provider Phụ (Anthropic/Gemini)")
            return self._call_provider(self.fallback, "provider-fallback", prompt)

        # Thử gọi Provider chính
        try:
            res = self._call_provider(self.primary, "provider-primary", prompt)
            self.failure_count = 0  # Reset khi thành công
            return res
        except Exception as e:
            self.failure_count += 1
            print(f"[WARN] Provider chính lỗi ({e}). Kích hoạt Fallback!")

            # Nếu lỗi liên tiếp 3 lần -> Mở mạch cách ly 60 giây
            if self.failure_count >= 3:
                self.circuit_open_until = current_time + 60.0
                print("[CIRCUIT TRIPPED] Tạm dừng gọi Provider chính trong 60 giây.")

            return self._call_provider(self.fallback, "provider-fallback", prompt)

    def _call_provider(self, client, provider_type: str, prompt: str) -> str:
        # Chuẩn hóa lời gọi API giữa các nhà cung cấp
        return client.execute(prompt)

