# Mô phỏng cách tính toán chỉ số Faithfulness của RAGAS bằng Prompt chuẩn
import json
from openai import OpenAI

client = OpenAI()

def compute_faithfulness_metric(context: str, answer: str) -> dict:
    """Thuật toán RAGAS Faithfulness: Đo tỷ lệ claims được Context bảo chứng."""
    step1_prompt = f"""
    Hãy phân rã câu trả lời sau thành danh sách các khẳng định độc lập (atomic statements):
    Câu trả lời: {answer}
    Trả về định dạng JSON: {{"statements": ["claim 1", "claim 2"]}}
    """
    res1 = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": step1_prompt}],
        response_format={"type": "json_object"}
    )
    statements = json.loads(res1.choices[0].message.content).get("statements", [])

    # Bước 2: Kiểm chứng từng statement với context
    step2_prompt = f"""
    Dưới đây là Context:
    {context}

    Hãy kiểm tra xem từng khẳng định sau có được Context chứng minh là ĐÚNG không:
    {json.dumps(statements, ensure_ascii=False)}

    Trả về JSON: {{"verdicts": [{{"claim": str, "supported": bool}}]}}
    """
    res2 = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": step2_prompt}],
        response_format={"type": "json_object"}
    )
    verdicts = json.loads(res2.choices[0].message.content).get("verdicts", [])

    supported_count = sum(1 for v in verdicts if v.get("supported"))
    faithfulness_score = supported_count / len(statements) if statements else 0.0

    return {
        "total_claims": len(statements),
        "supported_claims": supported_count,
        "faithfulness_score": round(faithfulness_score, 2),
        "details": verdicts
    }

