        self.old_embed = old_embedder
        self.new_embed = new_embedder
        self.active_read_target = "OLD"  # OLD hoặc NEW

    def ingest_document(self, doc_id: str, text: str):
        """Ghi đồng thời vào cả hai không gian vector trong giai đoạn chuyển giao."""
        # 1. Ghi vào kho hiện tại (đang phục vụ production)
        vec_old = self.old_embed.embed(text)
        self.old_store.upsert(doc_id, vec_old, metadata={"text": text})

        # 2. Ghi song song vào kho mới (đang chuẩn bị)
        try:
            vec_new = self.new_embed.embed(text)
            self.new_store.upsert(doc_id, vec_new, metadata={"text": text})
        except Exception as e:
            print(f"[WARN] Lỗi ghi sang New Store: {e}. Cần đẩy vào Dead Letter Queue.")

    def search(self, query: str, top_k: int = 5):
        """Chuyển hướng đọc tức thì chỉ bằng 1 thao tác đổi cờ biến."""
        if self.active_read_target == "OLD":
            q_vec = self.old_embed.embed(query)
            return self.old_store.search(q_vec, top_k)
        else:
            q_vec = self.new_embed.embed(query)
            return self.new_store.search(q_vec, top_k)

# Mô phỏng vòng lặp Iteration-Level Scheduler trong Continuous Batching
class ContinuousBatchingEngine:
    def __init__(self, max_batch_size: int = 4):
        self.max_batch_size = max_batch_size
        self.waiting_queue = []
        self.running_batch = []  # Danh sách các request đang chạy: [{'id': str, 'remaining_tokens': int}]

    def add_request(self, req_id: str, tokens_to_generate: int):
        self.waiting_queue.append({'id': req_id, 'remaining_tokens': tokens_to_generate})

    def step(self):
        """Mỗi bước step tương ứng với 1 lần sinh token trên toàn bộ batch (1 forward pass)."""
        # 1. Chèn request mới vào các slot trống nếu batch chưa đầy
        while len(self.running_batch) < self.max_batch_size and self.waiting_queue:
            new_req = self.waiting_queue.pop(0)
            self.running_batch.append(new_req)
            print(f"[Dynamic Insert] Nạp request {new_req['id']} vào batch đang chạy.")

        if not self.running_batch:
            return False  # Hết việc

        # 2. Sinh 1 token đồng loạt cho tất cả các request trong batch
        completed_requests = []
        for req in self.running_batch:
            req['remaining_tokens'] -= 1
            if req['remaining_tokens'] <= 0:
                completed_requests.append(req)

        # 3. Đẩy ngay các request đã hoàn thành ra khỏi batch (Early Eviction)
        for comp in completed_requests:
            self.running_batch.remove(comp)
            print(f"[Early Eviction] Request {comp['id']} hoàn thành sớm! Trả về cho client ngay lập tức.")

        return True

